CREATE TABLE question_bank_imports(import_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),offering_id uuid NOT NULL REFERENCES subject_offerings(offering_id),document_id uuid NOT NULL REFERENCES content_documents(document_id),question_set integer NOT NULL CHECK(question_set IN (1,2)),manifest jsonb NOT NULL,content_hash text NOT NULL,status text NOT NULL DEFAULT 'REVIEW' CHECK(status IN ('REVIEW','PUBLISHED','REJECTED')),created_by uuid NOT NULL REFERENCES app_users(user_id),reviewed_by uuid REFERENCES app_users(user_id),created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz,UNIQUE(offering_id,document_id,question_set,content_hash));
CREATE TABLE external_question_keys(document_id uuid NOT NULL REFERENCES content_documents(document_id),question_set integer NOT NULL CHECK(question_set IN (1,2)),external_id text NOT NULL,question_id uuid NOT NULL REFERENCES questions(question_id),content_hash text NOT NULL,PRIMARY KEY(document_id,question_set,external_id));
